import torch, sys
def verify():
    if not torch.cuda.is_available(): sys.exit(1)
    vram_gb = torch.cuda.get_device_properties(0).total_memory / (1024**3)
    if vram_gb < 15.0: sys.exit(1)
    print(f'Verified GPU: {torch.cuda.get_device_name(0)} ({vram_gb:.1f} GB)')
verify()

